fn test_any_all_subquery() {
    let sql = "SELECT * FROM r WHERE r.order_id = ANY (SELECT o.order_id FROM o)";
    pg().one_statement_parses_to(
        sql,
        "SELECT * FROM r WHERE r.order_id = ANY ((SELECT o.order_id FROM o))",
