#[test]
fn test_base_prefixed_integer_literals() {
    let sql = "SELECT 0xFF00, 0b1010, 0o17, 0x_0100";
    let stmt = pg().one_statement_parses_to(sql, sql);
    match stmt {
        Statement::Query(query) => match *query.body {
            SetExpr::Select(select) => {
                let projection = &select.projection;
                let SelectItem::UnnamedExpr(expr) = &projection[0] else {
                    panic!("expected select item");
                };
                let expected = vec![
                    Value::Number("0xFF00".to_string(), false),
                    Value::Number("0b1010".to_string(), false),
                    Value::Number("0o17".to_string(), false),
                    Value::Number("0x_0100".to_string(), false),
                ];
                let Expr::Tuple(exprs) = expr else {
                    panic!("expected tuple");
                };
                for (expr, expected) in exprs.iter().zip(expected) {
                    let Expr::Value(value) = expr else { panic!("expected value") };
                    assert_eq!(*value, expected);
                }
            }
            _ => panic!("expected select"),
        },
        _ => panic!("expected query"),
    }

    // Other dialects keep reading `0xFF00` as a hex string literal.
    let generic = GenericDialect {};
    let stmt = Parser::parse_sql(&generic, "SELECT 0xFF00").unwrap();
    let Statement::Query(query) = stmt.into_iter().next().unwrap() else {
        panic!("expected query");
    };
    let SetExpr::Select(select) = *query.body else { panic!("expected select") };
    let SelectItem::UnnamedExpr(expr) = &select.projection[0] else {
        panic!("expected select item");
    };
    assert_matches!(
        expr,
        Expr::Value(Value::HexStringLiteral(s)) if s == "FF00"
    );
}

#[test]
fn test_underscore_digit_separators() {
    let sql = "SELECT 10_000, 25_000.5, 1e1_0, -5_000";
    let expected = "SELECT 10_000, 25000.5, 10000, -5000";
    let stmt = pg().one_statement_parses_to(sql, expected);
    assert_eq!(stmt.to_string(), expected);

    // Underscores are only valid between two digits: PostgreSQL rejects
    // `1__0` and so do we (the leftover `_0` cannot continue the number).
    assert!(Parser::parse_sql(&PostgreSqlDialect {}, "SELECT 1__0").is_err());

    // Other dialects keep the old behavior.
    let generic = GenericDialect {};
    assert!(Parser::parse_sql(&generic, "SELECT 10_000").is_err());
}

#[test]
fn test_string_literal_line_continuation() {
    // String constants separated only by whitespace containing a newline
    // are one constant.
    let sql = "UPDATE support_tickets
SET resolution = 'Refund issued to customer.
'
WHERE id = 1";
    let stmt = pg().one_statement_parses_to(sql, sql);
    let Statement::Update(Update { assignments, .. }) = stmt else {
        panic!("expected update");
    };
    assert_matches!(
        &assignments[0].value,
        Expr::Value(Value::SingleQuotedString(s)) if *s == "Refund issued to customer.\n"
    );

    // Separated by whitespace without a newline: two constants.
    let stmt = pg().one_statement_parses_to(
        "SELECT 'foo' 'bar'",
        "SELECT 'foo', 'bar'",
    );
    assert_eq!(stmt.to_string(), "SELECT 'foo', 'bar'");

    // Other dialects do not concatenate.
    let generic = GenericDialect {};
    let stmt = Parser::parse_sql(&generic, "SELECT 'foo'\n'bar'").unwrap();
    let Statement::Query(query) = stmt.into_iter().next().unwrap() else {
        panic!("expected query");
    };
    let SetExpr::Select(select) = *query.body else { panic!("expected select") };
    let SelectItem::UnnamedExpr(Expr::Value(v)) = &select.projection[0] else {
        panic!("expected select item");
    };
    assert_eq!(*v, Value::SingleQuotedString("foo".to_string()));
}
